   SET CHARGING_TIME_BASED_ON_ABNORMAL_CHARGING = #{systemConfig.chargingTimeBasedOnAbnormalCharging}
      ,ABNORMAL_CHARGE_AMOUNT                    = #{systemConfig.abnormalChargeAmount}
      ,EMPLACEMENT                                = #{systemConfig.emplacement}
