      ,USE_HOME_NET                               = #{systemConfig.useHomeNet}
      ,FILE_STORE_PATH                            = #{systemConfig.fileStorePath}
      ,CUSTOMER_SUPPORT                           = #{systemConfig.customerSupport}
      ,DB_BACKUP_PATH                             = #{systemConfig.dbBackupPath}
      ,DB_BACKUP_CYCLE                            = #{systemConfig.dbBackupCycle}
      ,DB_BACKUP_RETENTION_PERIOD                 = #{systemConfig.dbBackupRetentionPeriod}
